#include <stdint.h>

// Mandatorily declared stack
uint64_t _stack[512];
uint64_t * const _stack_top = _stack + 512;

// Mandatory tohost declaration
extern volatile uint64_t tohost;

// Timing mechanism (rdcycle)
static inline uint64_t rdcycle() {
    uint64_t cycle;
    asm volatile ("rdcycle %0" : "=r"(cycle));
    return cycle;
}

// Global variables for attacker data (ensure cache misses)
// These 8 variables are used to cause 8 parallel D-cache misses,
// thereby occupying all 8 D-MSHRs. We rely on the simulator to
// treat these distinct global addresses as "cold" at the start of each trial
// to ensure L1/L2 D-cache misses without explicit flushing (which is banned).
static volatile uint64_t d_mshr_target_0;
static volatile uint64_t d_mshr_target_1;
static volatile uint64_t d_mshr_target_2;
static volatile uint64_t d_mshr_target_3;
static volatile uint64_t d_mshr_target_4;
static volatile uint64_t d_mshr_target_5;
static volatile uint64_t d_mshr_target_6;
static volatile uint64_t d_mshr_target_7;

// Function to saturate D-MSHRs.
// Performs 8 parallel loads to distinct global variables.
// These loads are expected to miss in L1/L2 D-cache, thus consuming D-MSHRs.
void prime_d_mshrs() {
    asm volatile (
        "lw x0, 0(%0)
" // Load to x0 (discard result)
        "lw x0, 0(%1)
"
        "lw x0, 0(%2)
"
        "lw x0, 0(%3)
"
        "lw x0, 0(%4)
"
        "lw x0, 0(%5)
"
        "lw x0, 0(%6)
"
        "lw x0, 0(%7)
"
        : // No output operands
        : "r"(&d_mshr_target_0), "r"(&d_mshr_target_1),
          "r"(&d_mshr_target_2), "r"(&d_mshr_target_3),
          "r"(&d_mshr_target_4), "r"(&d_mshr_target_5),
          "r"(&d_mshr_target_6), "r"(&d_mshr_target_7)
        : "memory" // Clobbers memory, ensures loads happen
    );
}

// Victim code - Function intended to be on a "known" I-TLB page.
// This function will be called once before measurements in the "hit" controls
// to ensure its page is in the I-TLB.
void __attribute__((naked)) victim_func_known_page() {
    asm volatile (
        "nop
"
        "nop
"
        "nop
"
        "nop
"
        "ret
"
    );
}

// Victim code - Function intended to be on an "unknown" I-TLB page.
// The __attribute__((aligned(4096))) attempts to place this function
// on a distinct memory page, which should cause an I-TLB miss upon first execution
// in a bare-metal environment without explicit I-TLB flushing (fence.i is banned).
void __attribute__((naked, aligned(4096))) victim_func_unknown_page() {
    asm volatile (
        "nop
"
        "nop
"
        "nop
"
        "nop
"
        "ret
"
    );
}

// Experiment runner function for a single trial
void run_experiment(int is_itlb_miss_case, int is_d_mshr_prime_case, uint64_t *results_array, int trial_idx) {
    uint64_t start_time, end_time;

    // Optional: Pre-warm the I-TLB with the "known" page for control cases
    // This ensures victim_func_known_page is in the I-TLB when it's supposed to be a hit.
    if (!is_itlb_miss_case) {
        victim_func_known_page();
    }
    // Add NOPs to ensure pipeline settles before timing.
    asm volatile("nop;nop;nop;nop;nop;nop;nop;nop;");

    // Start measurement
    start_time = rdcycle();

    // Attacker: Prime D-MSHRs
    if (is_d_mshr_prime_case) {
        prime_d_mshrs();
    }
    // Add NOPs to ensure pipeline settles before victim.
    asm volatile("nop;nop;nop;nop;nop;nop;nop;nop;");

    // Victim: Cause I-TLB miss or hit
    if (is_itlb_miss_case) {
        // Call the function on the potentially "cold" page.
        // This is expected to cause an I-TLB miss.
        victim_func_unknown_page();
    } else {
        // Call the function on the "warmed" page.
        // This is expected to be an I-TLB hit.
        victim_func_known_page();
    }

    // End measurement
    end_time = rdcycle();
    results_array[trial_idx] = end_time - start_time;
}

// Main function
void main() {
    // Number of trials per condition. Total iterations 4 * NUM_TRIALS = 80.
    // Well within the 50,000 total work cap.
    #define NUM_TRIALS 20

    // Arrays to store timing results for each condition
    static uint64_t results_prime_itlb_miss[NUM_TRIALS];
    static uint64_t results_no_prime_itlb_miss[NUM_TRIALS];
    static uint64_t results_prime_itlb_hit[NUM_TRIALS];
    static uint64_t results_no_prime_itlb_hit[NUM_TRIALS];

    printf("Starting D-MSHR-PTW experiment...
");

    // Initialize D-MSHR targets once. This ensures they are "dirty" and might force
    // simulator to treat them as cold for subsequent reads.
    d_mshr_target_0 = 0;
    d_mshr_target_1 = 1;
    d_mshr_target_2 = 2;
    d_mshr_target_3 = 3;
    d_mshr_target_4 = 4;
    d_mshr_target_5 = 5;
    d_mshr_target_6 = 6;
    d_mshr_target_7 = 7;

    // --- Experiment Trials ---

    printf("Running with D-MSHR prime, I-TLB miss (Attack scenario)...
");
    for (int i = 0; i < NUM_TRIALS; i++) {
        run_experiment(1, 1, results_prime_itlb_miss, i);
    }

    printf("Running without D-MSHR prime, I-TLB miss (Control 1: I-TLB miss only)...
");
    for (int i = 0; i < NUM_TRIALS; i++) {
        run_experiment(1, 0, results_no_prime_itlb_miss, i);
    }

    // --- Positive Control ---
    // This control confirms that the D-MSHR priming itself doesn't significantly
    // interfere with an I-TLB *hit* case.
    printf("Running with D-MSHR prime, I-TLB hit (Control 2: D-MSHR prime, I-TLB hit).
");
    for (int i = 0; i < NUM_TRIALS; i++) {
        run_experiment(0, 1, results_prime_itlb_hit, i);
    }

    // --- Baseline Control ---
    // This control provides the baseline execution time for a victim I-TLB hit
    // without any D-MSHR priming.
    printf("Running without D-MSHR prime, I-TLB hit (Control 3: Baseline).
");
    for (int i = 0; i < NUM_TRIALS; i++) {
        run_experiment(0, 0, results_no_prime_itlb_hit, i);
    }

    // --- Print Results ---

    printf("
Results (cycles):
");

    printf("ATTACK SCENARIO (Prime D-MSHR + I-TLB Miss):
");
    for (int i = 0; i < NUM_TRIALS; i++) {
        printf("%lu
", results_prime_itlb_miss[i]);
    }

    printf("CONTROL 1 (No Prime + I-TLB Miss):
");
    for (int i = 0; i < NUM_TRIALS; i++) {
        printf("%lu
", results_no_prime_itlb_miss[i]);
    }

    printf("CONTROL 2 (Prime D-MSHR + I-TLB Hit):
");
    for (int i = 0; i < NUM_TRIALS; i++) {
        printf("%lu
", results_prime_itlb_hit[i]);
    }

    printf("CONTROL 3 (No Prime + I-TLB Hit - Baseline):
");
    for (int i = 0; i < NUM_TRIALS; i++) {
        printf("%lu
", results_no_prime_itlb_hit[i]);
    }

    printf("Experiment finished. Signalling tohost.
");
    tohost = 1; // Signal simulation termination
    while (1) {} // Mandatory infinite loop after termination signal
}

// Mandatory trap handler for bare-metal RISC-V.
// It is __attribute__((naked)) with inline asm and uses 'mret'.
// For this simple experiment, we assume no traps will occur, so it just returns.
void __attribute__((naked)) trap_handler() {
    // In a real scenario, this would save registers, handle the trap type,
    // potentially switch stacks, and then restore and return.
    // For this experiment, we anticipate no traps.
    asm volatile (
        "mret
"
    );
}

// Mandatory _start function to set up the stack and call main.
// Also sets the Machine Trap-Vector Base Address (mtvec) to our trap_handler.
void _start() {
    // Set up stack pointer to _stack_top
    asm volatile("mv sp, %0" :: "r"(_stack_top));

    // Set MTVEC to point to the trap handler
    asm volatile("csrw mtvec, %0" :: "r"(&trap_handler));

    // Call main function to begin the experiment
    main();
}

